mapper.select:
SELECT id, token_version, `status`
FROM t_user
WHERE id = #{id}

mapper.update:
UPDATE t_user
SET sms_verified_at = #{now}, updated_at = #{now}
WHERE id = #{id}

UPDATE t_user
SET last_login_at = #{now}, updated_at = #{now}
WHERE id = #{id}

UPDATE t_user
SET password_hash = #{passwordHash},
    token_version = token_version + 1,
    updated_at = #{now}
WHERE id = #{id}

UPDATE t_user
SET phone = #{phone},
    token_version = token_version + 1,
    sms_verified_at = #{now},
    updated_at = #{now}
WHERE id = #{id}

UPDATE t_user
SET recovery_code_hash = #{recoveryCodeHash},
    recovery_code_created_at = #{now},
    updated_at = #{now}
WHERE id = #{id}

UPDATE t_user
SET token_version = token_version + 1,
    updated_at = #{now}
WHERE id = #{id}
